const express = require('express');
const app = express();

app.use(express.json());

// --- Safe rule engine ---------------------------------------------------
//
// NOTE: docs/RULES_ENGINE.md proposes evaluating caller-supplied rules with
// `Function('ctx','req', 'return (' + expr + ')')`. That is a remote code
// execution vulnerability: any client could run arbitrary code on the server
// (read files, exfiltrate secrets, spawn processes). We do NOT use that
// approach. Instead we parse a small, restricted expression grammar that
// covers the documented use case (e.g. `ctx.amount > 100`) safely.
//
// Supported grammar:
//   expr      := orExpr
//   orExpr    := andExpr ( "||" andExpr )*
//   andExpr   := comparison ( "&&" comparison )*
//   comparison:= operand OP operand            OP in > >= < <= == !=
//   operand   := path | number | quotedString | true | false | null
//   path      := ident ( "." ident )*          resolved against { ctx }
//
// No function calls, no property access beyond plain dotted paths, no
// prototype access, no side effects.

const OPERATORS = ['>=', '<=', '==', '!=', '>', '<'];

function tokenize(expr) {
  const tokens = [];
  let i = 0;
  const isIdentStart = (c) => /[A-Za-z_$]/.test(c);
  const isIdentPart = (c) => /[A-Za-z0-9_$.]/.test(c);
  while (i < expr.length) {
    const c = expr[i];
    if (/\s/.test(c)) { i++; continue; }
    if (c === '&' && expr[i + 1] === '&') { tokens.push({ t: 'and' }); i += 2; continue; }
    if (c === '|' && expr[i + 1] === '|') { tokens.push({ t: 'or' }); i += 2; continue; }
    if (c === '(') { tokens.push({ t: 'lparen' }); i++; continue; }
    if (c === ')') { tokens.push({ t: 'rparen' }); i++; continue; }
    const op = OPERATORS.find((o) => expr.startsWith(o, i));
    if (op) { tokens.push({ t: 'op', v: op }); i += op.length; continue; }
    if (c === '"' || c === "'") {
      let j = i + 1; let s = '';
      while (j < expr.length && expr[j] !== c) {
        if (expr[j] === '\\') { s += expr[j + 1]; j += 2; } else { s += expr[j]; j++; }
      }
      if (j >= expr.length) throw new Error('Unterminated string literal');
      tokens.push({ t: 'string', v: s }); i = j + 1; continue;
    }
    if (/[0-9]/.test(c) || (c === '-' && /[0-9]/.test(expr[i + 1] || ''))) {
      let j = i + (c === '-' ? 1 : 0);
      while (j < expr.length && /[0-9.]/.test(expr[j])) j++;
      const num = Number(expr.slice(i, j));
      if (Number.isNaN(num)) throw new Error('Invalid number');
      tokens.push({ t: 'number', v: num }); i = j; continue;
    }
    if (isIdentStart(c)) {
      let j = i;
      while (j < expr.length && isIdentPart(expr[j])) j++;
      tokens.push({ t: 'ident', v: expr.slice(i, j) }); i = j; continue;
    }
    throw new Error(`Unexpected character '${c}' in rule`);
  }
  return tokens;
}

function resolvePath(path, ctx) {
  if (path === 'true') return true;
  if (path === 'false') return false;
  if (path === 'null') return null;
  const parts = path.split('.');
  const forbidden = new Set(['__proto__', 'prototype', 'constructor']);
  let cur = { ctx };
  for (const p of parts) {
    if (p === '' || forbidden.has(p)) throw new Error('Invalid path segment');
    if (cur == null || typeof cur !== 'object') return undefined;
    cur = cur[p];
  }
  return cur;
}

function parse(tokens, ctx) {
  let pos = 0;
  const peek = () => tokens[pos];
  const next = () => tokens[pos++];

  function operandValue(tok) {
    if (tok.t === 'number' || tok.t === 'string') return tok.v;
    if (tok.t === 'ident') return resolvePath(tok.v, ctx);
    throw new Error('Expected operand');
  }

  function parsePrimary() {
    const tok = peek();
    if (!tok) throw new Error('Unexpected end of rule');
    if (tok.t === 'lparen') {
      next();
      const v = parseOr();
      if (!peek() || peek().t !== 'rparen') throw new Error('Missing )');
      next();
      return v;
    }
    // comparison: operand OP operand
    const left = operandValue(next());
    if (peek() && peek().t === 'op') {
      const op = next().v;
      const right = operandValue(next());
      switch (op) {
        case '>': return left > right;
        case '>=': return left >= right;
        case '<': return left < right;
        case '<=': return left <= right;
        case '==': return left === right;
        case '!=': return left !== right;
      }
    }
    return Boolean(left);
  }

  function parseAnd() {
    let v = parsePrimary();
    while (peek() && peek().t === 'and') { next(); const r = parsePrimary(); v = v && r; }
    return v;
  }

  function parseOr() {
    let v = parseAnd();
    while (peek() && peek().t === 'or') { next(); const r = parseAnd(); v = v || r; }
    return v;
  }

  const result = parseOr();
  if (pos !== tokens.length) throw new Error('Unexpected tokens after expression');
  return result;
}

function evalRule(rule, context) {
  if (typeof rule !== 'string') throw new Error('rule must be a string');
  if (rule.length > 1000) throw new Error('rule too long');
  const tokens = tokenize(rule);
  return Boolean(parse(tokens, context || {}));
}

app.post('/check', (req, res) => {
  const { rule, context } = req.body || {};
  if (typeof rule !== 'string' || rule.trim() === '') {
    return res.status(400).json({ error: 'A non-empty "rule" string is required' });
  }
  try {
    const result = evalRule(rule, context);
    res.json({ result, rule });
  } catch (err) {
    res.status(400).json({ error: `Invalid rule: ${err.message}` });
  }
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

